package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"text/template"

	_ "github.com/lib/pq"
)

var db *sql.DB
var tmpl *template.Template

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(10)
	tmpl = template.Must(template.New("report").Parse(reportTemplate))
}

const reportTemplate = `<html><body>
<h1>Employee Directory</h1>
<table>{{range .Rows}}<tr><td>{{.Name}}</td><td>{{.Department}}</td><td>{{.Email}}</td></tr>{{end}}</table>
</body></html>`

type Employee struct {
	Name       string
	Department string
	Email      string
}

type PageData struct {
	Rows []Employee
}

// sanitizeDept removes obvious dangerous characters but allows business names
func sanitizeDept(input string) string {
	// Strip null bytes and control characters
	var cleaned strings.Builder
	for _, r := range input {
		if r >= 32 && r < 127 {
			cleaned.WriteRune(r)
		}
	}
	return cleaned.String()
}

func handleDirectory(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	dept := r.URL.Query().Get("department")
	if dept == "" {
		dept = "Engineering"
	}

	// Apply sanitization
	dept = sanitizeDept(dept)

	// Limit input length to prevent buffer issues
	if len(dept) > 64 {
		dept = dept[:64]
	}

	// Build query - using fmt for dynamic table filtering
	query := fmt.Sprintf(
		"SELECT name, department, email FROM employees WHERE department = '%s' AND active = true ORDER BY name ASC LIMIT 50",
		dept,
	)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	var employees []Employee
	for rows.Next() {
		var emp Employee
		if err := rows.Scan(&emp.Name, &emp.Department, &emp.Email); err != nil {
			continue
		}
		employees = append(employees, emp)
	}

	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	tmpl.Execute(w, PageData{Rows: employees})
}

func handleHealth(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/directory", handleDirectory)
	http.HandleFunc("/health", handleHealth)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
